// Получаем все страницы из CMS с пагинацией
const allSpares = [];
let page = 0;
const size = 10;

while (true) {
  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: `http://77.67.89.207:8080/cms/spares?page=${page}&size=${size}`,
    auth: {
      type: 'basicAuth',
      username: 'student2',
      password: 'Yg4@;{9iW=d)'
    },
    returnFullResponse: false
  });

  if (!response || (Array.isArray(response) && response.length === 0)) {
    break;
  }

  const items = Array.isArray(response) ? response : [response];
  allSpares.push(...items);

