return allSpares.map(item => ({ json: item }));

// Формируем CSV без заголовка, разделитель ';', кодировка UTF-8
const items = $input.all();
const token = $('Get Bearer Token').first().json.token;

const csvLines = items.map(item => {
  const d = item.json;
  return [
    d.spare_code,
    d.spare_name,
    d.spare_description,
    d.spare_type,
    d.spare_status,
    d.price,
    d.quantity,
    d.updated_at
  ].join(';');
});

const csvContent = csvLines.join('\n');

return [{ json: { csv: csvContent, token: token } }];
